        """Freeze task information and stacks at the time of capture."""
        async def capture_running():
            running = list(self.format_running_task_list("", False))
            stacks = {}
            for item in running:
                try:
                    stacks[item.task_id] = list(self.format_running_task_stack(item.task_id))
                except MissingTask:
                    continue
            return running, stacks

        if asyncio.get_running_loop() is self._monitored_loop:
            running, stacks = await capture_running()
        else:
            running, stacks = await asyncio.wrap_future(
                asyncio.run_coroutine_threadsafe(capture_running(), self._monitored_loop)
            )
        terminated = list(self.format_terminated_task_list("", False))
        for item in terminated:
            try:
                stacks[item.task_id] = list(self.format_terminated_task_stack(item.task_id))
            except KeyError:
                pass
        with self._snapshot_lock:
            snapshot_id = self._next_snapshot_id
            self._next_snapshot_id += 1
            self._snapshots[snapshot_id] = Snapshot(
                snapshot_id, name, running, terminated, stacks
            )
            while len(self._snapshots) > self._max_snapshots:
                oldest = next((sid for sid, snap in self._snapshots.items()
                               if snap.name is None), None)
                if oldest is None:
                    break
                del self._snapshots[oldest]
            return snapshot_id

    def list_snapshots(self) -> List[SnapshotSummary]:
        with self._snapshot_lock:
            return [SnapshotSummary(s.id, s.name, len(s.running), len(s.terminated))
                    for s in self._snapshots.values()]

    def get_snapshot(self, snapshot_id: int) -> Snapshot:
        with self._snapshot_lock:
            try:
                return copy.deepcopy(self._snapshots[int(snapshot_id)])
            except (ValueError, TypeError, KeyError):
                raise KeyError(snapshot_id) from None

    def delete_snapshot(self, snapshot_id: int) -> None:
        with self._snapshot_lock:
            try:
                del self._snapshots[int(snapshot_id)]
            except (ValueError, TypeError, KeyError):
                raise KeyError(snapshot_id) from None

    def format_snapshot_task_list(self, snapshot_id: int) -> Sequence[FormattedLiveTaskInfo]:
