    def format_snapshot_task_stack(self, snapshot_id: int, task_id: str | int) -> Sequence[FormattedStackItem]:
        return self.get_snapshot(snapshot_id).stacks[str(task_id)]

    def format_snapshot_diff(self, snapshot_id_1: int, snapshot_id_2: int) -> SnapshotDiff:
